// Catalog enrichment: constellation, visible colour, planets (confirmed + potential),
// mass, and measured composition. Every value comes from a cited catalog or an
// established algorithm applied to measured data; anything not available stays null
// and the game shows "unknown". No values are generated by an LLM.

import { readFile } from "node:fs/promises";
import { join } from "node:path";

export const ENRICH_SOURCES = {
  constellations: { title: "IAU constellation boundaries (Delporte 1930), as tabulated for B1875.0", citation: "Roman, N. G. 1987, PASP 99, 695 (CDS VI/42)", url: "https://cdsarc.cds.unistra.fr/viz-bin/cat/VI/42" },
  colourSequence: { title: "A Modern Mean Dwarf Stellar Color and Effective Temperature Sequence", citation: "Pecaut & Mamajek 2013, ApJS 208, 9 (table version used is cached)", url: "https://www.pas.rochester.edu/~emamajek/EEM_dwarf_UBVIJHK_colors_Teff.txt" },
  blackbodyColour: { title: "What color is a blackbody? (sRGB, CIE 1964 10° observer)", citation: "Charity, M. 2001, vendian.org", url: "http://www.vendian.org/mncharity/dir3/blackbody/" },
  exoplanets: { title: "NASA Exoplanet Archive, Planetary Systems Composite Parameters (confirmed planets)", citation: "NASA Exoplanet Science Institute (2026)", url: "https://exoplanetarchive.ipac.caltech.edu/" },
  tess: { title: "NASA Exoplanet Archive, TESS Objects of Interest (planet candidates, disposition PC/APC)", citation: "NASA Exoplanet Science Institute (2026)", url: "https://exoplanetarchive.ipac.caltech.edu/" },
  gaiaAp: { title: "Gaia DR3 astrophysical parameters (FLAME masses; GSP-Spec metallicity, best-quality flags only)", citation: "Creevey et al. 2023; Recio-Blanco et al. 2023, A&A 674", url: "https://gea.esac.esa.int/archive/" },
};

export const AP_QUERY = "SELECT ap.source_id, ap.mass_flame, ap.mass_flame_lower, ap.mass_flame_upper, ap.mh_gspspec, ap.mh_gspspec_lower, ap.mh_gspspec_upper, ap.flags_gspspec FROM gaiadr3.astrophysical_parameters AS ap JOIN gaiadr3.gaia_source AS g ON g.source_id = ap.source_id WHERE (g.parallax > 32.6 OR g.phot_g_mean_mag < 6.5) AND g.parallax_over_error > 10";
export const PLANETS_QUERY = "select pl_name,hostname,gaia_dr3_id,ra,dec,sy_dist,st_mass,st_masserr1,st_masserr2,st_met,st_meterr1,st_metratio from pscomppars where sy_dist < 33";
export const TOI_QUERY = "select toi,tid,ra,dec,st_dist,tfopwg_disp from toi where st_dist < 33 and tfopwg_disp in ('PC','APC')";

// Visible-colour classes by temperature. Names follow the conventional colour descriptions of
// the stellar spectral classes; the swatch is a blackbody at the class's middle temperature.
export const COLOUR_CLASSES = [
  { name: "blue", min: 30000, ref: 35000, classes: "O" },
  { name: "blue-white", min: 20000, ref: 24000, classes: "early B" },
  { name: "bluish white", min: 10000, ref: 13000, classes: "late B" },
  { name: "white", min: 7500, ref: 8600, classes: "A" },
  { name: "yellow-white", min: 6000, ref: 6700, classes: "F" },
  { name: "yellow", min: 5200, ref: 5700, classes: "G" },
  { name: "light orange", min: 4600, ref: 4900, classes: "early K" },
  { name: "orange", min: 3900, ref: 4200, classes: "late K" },
  { name: "orange-red", min: 3300, ref: 3600, classes: "early M" },
  { name: "red", min: 2700, ref: 3000, classes: "mid-to-late M" },
  { name: "deep red", min: 2000, ref: 2300, classes: "late M / L brown dwarfs" },
  { name: "dark red (glows mostly in infrared)", min: 0, ref: 1500, classes: "L / T / Y brown dwarfs" },
];

const CONSTELLATIONS = {
  And: "Andromeda", Ant: "Antlia", Aps: "Apus", Aqr: "Aquarius", Aql: "Aquila", Ara: "Ara", Ari: "Aries", Aur: "Auriga", Boo: "Boötes", Cae: "Caelum",
  Cam: "Camelopardalis", Cnc: "Cancer", CVn: "Canes Venatici", CMa: "Canis Major", CMi: "Canis Minor", Cap: "Capricornus", Car: "Carina", Cas: "Cassiopeia",
  Cen: "Centaurus", Cep: "Cepheus", Cet: "Cetus", Cha: "Chamaeleon", Cir: "Circinus", Col: "Columba", Com: "Coma Berenices", CrA: "Corona Australis",
  CrB: "Corona Borealis", Crv: "Corvus", Crt: "Crater", Cru: "Crux", Cyg: "Cygnus", Del: "Delphinus", Dor: "Dorado", Dra: "Draco", Equ: "Equuleus",
  Eri: "Eridanus", For: "Fornax", Gem: "Gemini", Gru: "Grus", Her: "Hercules", Hor: "Horologium", Hya: "Hydra", Hyi: "Hydrus", Ind: "Indus", Lac: "Lacerta",
  Leo: "Leo", LMi: "Leo Minor", Lep: "Lepus", Lib: "Libra", Lup: "Lupus", Lyn: "Lynx", Lyr: "Lyra", Men: "Mensa", Mic: "Microscopium", Mon: "Monoceros",
  Mus: "Musca", Nor: "Norma", Oct: "Octans", Oph: "Ophiuchus", Ori: "Orion", Pav: "Pavo", Peg: "Pegasus", Per: "Perseus", Phe: "Phoenix", Pic: "Pictor",
  Psc: "Pisces", PsA: "Piscis Austrinus", Pup: "Puppis", Pyx: "Pyxis", Ret: "Reticulum", Sge: "Sagitta", Sgr: "Sagittarius", Sco: "Scorpius", Scl: "Sculptor",
  Sct: "Scutum", Ser: "Serpens", Sex: "Sextans", Tau: "Taurus", Tel: "Telescopium", Tri: "Triangulum", TrA: "Triangulum Australe", Tuc: "Tucana",
  UMa: "Ursa Major", UMi: "Ursa Minor", Vel: "Vela", Vir: "Virgo", Vol: "Volans", Vul: "Vulpecula",
};
export const ZODIAC = ["Ari", "Tau", "Gem", "Cnc", "Leo", "Vir", "Lib", "Sco", "Sgr", "Cap", "Aqr", "Psc"];

// ---------- constellation from position (Roman 1987) ----------
const D2R = Math.PI / 180;
function precessJ2000To(raDeg, decDeg, jd) {
  // IAU 1976 precession from J2000.0 to epoch jd (Lieske et al. 1977).
  const t = (jd - 2451545.0) / 36525;
  const as = (x) => (x / 3600) * D2R;
  const zeta = as(2306.2181 * t + 0.30188 * t * t + 0.017998 * t ** 3);
  const z = as(2306.2181 * t + 1.09468 * t * t + 0.018203 * t ** 3);
  const theta = as(2004.3109 * t - 0.42665 * t * t - 0.041833 * t ** 3);
  const a = raDeg * D2R, d = decDeg * D2R;
  const A = Math.cos(d) * Math.sin(a + zeta);
  const B = Math.cos(theta) * Math.cos(d) * Math.cos(a + zeta) - Math.sin(theta) * Math.sin(d);
  const C = Math.sin(theta) * Math.cos(d) * Math.cos(a + zeta) + Math.cos(theta) * Math.sin(d);
  return { ra: ((Math.atan2(A, B) + z) / D2R + 720) % 360, dec: Math.asin(C) / D2R };
}
const B1875 = 2405889.258550475;

function constellationFinder(boundsText) {
  const rows = boundsText.split("\n").filter((l) => l.trim()).map((l) => {
    const [raLo, raHi, decLo, con] = l.trim().split(/\s+/);
    return { raLo: Number(raLo), raHi: Number(raHi), decLo: Number(decLo), con };
  });
  return (raDeg, decDeg) => {
    const p = precessJ2000To(raDeg, decDeg, B1875);
    const raH = p.ra / 15;
    for (const r of rows) if (p.dec >= r.decLo && raH >= r.raLo && raH < r.raHi) return r.con;
    return null;
  };
}

// ---------- colour ----------
function mamajekSequence(text) {
  const lines = text.split("\n");
  const start = lines.findIndex((l) => l.startsWith("#SpT"));
  const head = lines[start].replace(/^#/, "").trim().split(/\s+/);
  const col = (n) => head.indexOf(n);
  const rows = [];
  for (let i = start + 1; i < lines.length; i++) {
    const l = lines[i];
    if (!l.trim() || l.startsWith("#")) break;
    const f = l.trim().split(/\s+/);
    const num = (k) => { const v = Number(f[col(k)]); return Number.isFinite(v) ? v : null; };
    rows.push({ teff: num("Teff"), bv: num("B-V"), bprp: num("Bp-Rp") });
  }
  // Colour → temperature by interpolation on the measured colour index.
  const curve = (key) => rows.filter((r) => r[key] != null && r.teff != null).sort((a, b) => a[key] - b[key]);
  const interp = (pts, key) => (x) => {
    if (x == null || !pts.length) return null;
    if (x <= pts[0][key] || x >= pts.at(-1)[key]) return null; // outside the calibrated range: don't extrapolate
    let i = 1;
    while (pts[i][key] < x) i++;
    const a = pts[i - 1], b = pts[i];
    const f = (x - a[key]) / (b[key] - a[key] || 1);
    return Math.exp(Math.log(a.teff) + f * (Math.log(b.teff) - Math.log(a.teff)));
  };
  return { fromBpRp: interp(curve("bprp"), "bprp"), fromBV: interp(curve("bv"), "bv") };
}

function blackbodyHex(text) {
  const table = text.split("\n").filter((l) => /^\s*\d+ K\s+10deg/.test(l)).map((l) => {
    const f = l.trim().split(/\s+/);
    return { t: Number(f[0]), hex: f.at(-1) };
  });
  return (teff) => {
    let best = table[0];
    for (const r of table) if (Math.abs(r.t - teff) < Math.abs(best.t - teff)) best = r;
    return best.hex;
  };
}

export const colourClassFor = (teff) => COLOUR_CLASSES.findIndex((c) => teff >= c.min);

// ---------- helpers ----------
function parseCsv(text) {
  const rows = [];
  let row = [], field = "", q = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (q) { if (ch === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else q = false; } else field += ch; }
    else if (ch === '"') q = true;
    else if (ch === ",") { row.push(field); field = ""; }
    else if (ch === "\n" || ch === "\r") { if (ch === "\r" && text[i + 1] === "\n") i++; row.push(field); field = ""; if (row.length > 1 || row[0] !== "") rows.push(row); row = []; }
    else field += ch;
  }
  if (field || row.length) { row.push(field); rows.push(row); }
  const [head, ...data] = rows;
  return data.map((r) => Object.fromEntries(head.map((h, i) => [h.trim(), r[i] ?? ""])));
}
const n = (s) => (s === "" || s == null ? null : Number(s));
function angSep(ra1, d1, ra2, d2) {
  const c = Math.sin(d1 * D2R) * Math.sin(d2 * D2R) + Math.cos(d1 * D2R) * Math.cos(d2 * D2R) * Math.cos((ra1 - ra2) * D2R);
  return Math.acos(Math.min(1, Math.max(-1, c))) / D2R;
}

// Position match for catalogs without Gaia DR3 ids: within 3′ (allows for proper motion
// between epochs) and 10% in distance — or within 1′ regardless of distance, because a few
// archive entries carry wrong distances (e.g. GJ 411 listed at 5.68 pc; Gaia gives 2.55 pc).
function positionMatcher(objects) {
  const withPos = objects.filter((o) => o.ra != null && o.dec != null && o.d && o.type === "star");
  return (ra, dec, dLy, { trustDistance = true } = {}) => {
    let best = null, bestSep = 3 / 60, within = 0;
    for (const o of withPos) {
      if (Math.abs(o.dec - dec) > 0.1) continue;
      const s = angSep(o.ra, o.dec, ra, dec);
      if (s >= 3 / 60) continue;
      within++;
      const distOk = !dLy || Math.abs(o.d - dLy) / dLy < 0.1;
      if (s < bestSep && (distOk || s < 1 / 60 || !trustDistance)) { best = o; bestSep = s; }
    }
    // Without distance agreement, only accept an unambiguous match (the one star within 3′).
    if (best && !trustDistance && within > 1 && dLy && Math.abs(best.d - dLy) / dLy >= 0.1) return null;
    return best;
  };
}

// ---------- main ----------
export async function enrich(objects, { cached, gaiaAsync, tapSync, root, LY_PER_PC, STAR_DATA }) {
  const stats = { constellation: 0, colour: 0, colourFrom: { bp_rp: 0, b_v: 0 }, mass: { flame: 0, exoplanetArchive: 0, research: 0 }, composition: { gaia: 0, exoplanetArchive: 0 }, planetsConfirmedHosts: 0, planetsConfirmed: 0, planetsUnmatched: [], potential: { tess: 0, research: 0 }, gspspecRejected: 0 };

  const conOf = constellationFinder(await cached("constellation_bounds_VI42.dat", () => fetch("https://cdsarc.cds.unistra.fr/ftp/VI/42/data.dat").then((r) => r.text())));
  const seq = mamajekSequence(await cached("mamajek_dwarfs.txt", () => fetch(ENRICH_SOURCES.colourSequence.url).then((r) => r.text())));
  const hexOf = blackbodyHex(await cached("bbr_color.txt", () => fetch("http://www.vendian.org/mncharity/dir3/blackbody/UnstableURLs/bbr_color.txt").then((r) => r.text())));
  const apRows = parseCsv(await cached("gaia_dr3_ap_100ly.csv", () => gaiaAsync(AP_QUERY)));
  const planetRows = parseCsv(await cached("exoplanets_pscomppars.csv", () => tapSync(PLANETS_QUERY)));
  const toiRows = parseCsv(await cached("exoplanets_toi_candidates.csv", () => tapSync(TOI_QUERY)));

  const byGaia = new Map(objects.filter((o) => o.ids?.gaia).map((o) => [o.ids.gaia, o]));
  const findByPos = positionMatcher(objects);

  // Constellation and colour for every star with a sky position.
  for (const o of objects) {
    if (o.ra != null && o.dec != null) {
      const con = conOf(o.ra, o.dec);
      if (con) { o.con = con; o.conName = CONSTELLATIONS[con] || con; stats.constellation++; }
    }
    if (o.type !== "star") continue;
    let t = null, from = null;
    if (o.c != null) { t = seq.fromBpRp(o.c); from = "bp_rp"; }
    if (t == null && o.bv != null) { t = seq.fromBV(o.bv); from = "b_v"; }
    if (t != null) {
      o.tc = Math.round(t / 50) * 50;           // colour temperature, K
      o.cc = colourClassFor(o.tc);              // colour class index
      o.hex = hexOf(o.tc);                      // blackbody sRGB at that temperature
      o.ccFrom = from;
      stats.colour++; stats.colourFrom[from]++;
    }
  }

  // Gaia DR3: FLAME mass; GSP-Spec metallicity only with the best-quality flags
  // (first 13 flags all zero; Recio-Blanco et al. 2023).
  for (const r of apRows) {
    const o = byGaia.get(`Gaia DR3 ${r.source_id}`);
    if (!o) continue;
    if (n(r.mass_flame) != null) {
      o.mass = { v: +n(r.mass_flame).toFixed(3), lo: n(r.mass_flame_lower), hi: n(r.mass_flame_upper), src: "gaiaAp" };
      stats.mass.flame++;
    }
    if (n(r.mh_gspspec) != null) {
      const good = /^0{13}/.test(r.flags_gspspec || "");
      if (good) { o.mh = { v: n(r.mh_gspspec), lo: n(r.mh_gspspec_lower), hi: n(r.mh_gspspec_upper), kind: "[M/H]", src: "gaiaAp" }; stats.composition.gaia++; }
      else stats.gspspecRejected++;
    }
  }

  // Confirmed planets per host (NASA Exoplanet Archive), plus host mass / metallicity.
  const hostOf = new Map();
  for (const r of planetRows) {
    let o = r.gaia_dr3_id ? byGaia.get(r.gaia_dr3_id) : null;
    if (!o) o = findByPos(n(r.ra), n(r.dec), n(r.sy_dist) * LY_PER_PC);
    // No Gaia id and no distance agreement: some archive distances are wrong (GJ 411 is listed
    // at 5.68 pc; Gaia: 2.55 pc), so fall back to an unambiguous sky match.
    if (!o && !r.gaia_dr3_id) o = findByPos(n(r.ra), n(r.dec), n(r.sy_dist) * LY_PER_PC, { trustDistance: false });
    if (!o) { if (!stats.planetsUnmatched.includes(r.hostname)) stats.planetsUnmatched.push(r.hostname); continue; }
    hostOf.set(r.hostname, o);
    o.plC = (o.plC || 0) + 1;
    o.plHost = r.hostname;
    stats.planetsConfirmed++;
    if (!o.mass && n(r.st_mass) != null) { o.mass = { v: n(r.st_mass), lo: null, hi: null, src: "exoplanets" }; stats.mass.exoplanetArchive++; }
    if (!o.mh && n(r.st_met) != null) { o.mh = { v: n(r.st_met), kind: r.st_metratio || "[Fe/H]", src: "exoplanets" }; stats.composition.exoplanetArchive++; }
  }
  stats.planetsConfirmedHosts = new Set([...hostOf.values()].map((o) => o.id)).size;

  // Potential planets: TESS candidates (PC/APC) ...
  for (const r of toiRows) {
    const o = findByPos(n(r.ra), n(r.dec), n(r.st_dist) * LY_PER_PC);
    if (!o) continue;
    o.plP = (o.plP || 0) + 1;
    (o.plPSrc ||= new Set()).add("tess");
    stats.potential.tess++;
  }
  // ... and unconfirmed / debated claims from the nearby-system research batches
  // (refuted, retracted or disproven claims are not counted).
  const research = [];
  for (let g = 1; g <= 5; g++) {
    try { research.push(...JSON.parse(await readFile(join(root, "research", `stars_group${g}.json`), "utf8"))); } catch {}
  }
  const REFUTED = /refut|retract|disprov|ruled out|false positive|not confirmed by|spurious|activity/i;
  const OPEN = /candidate|unconfirmed|debated|disputed|suspected|hypothetical|possible|preprint|unverified/i;
  for (const e of research) {
    const name = e.name.replace(/\s*\([^)]*\)$/, "");
    const sys = objects.find((o) => o.type === "star system" && o.name === name);
    if (!sys) continue;
    const open = (e.candidates || []).filter((c) => OPEN.test(`${c.status} ${c.note}`) && !REFUTED.test(`${c.status}`));
    if (open.length) {
      sys.plP = (sys.plP || 0) + open.length;
      (sys.plPSrc ||= new Set()).add("research");
      sys.plPNames = open.map((c) => c.name);
      stats.potential.research += open.length;
      if (sys.components?.length === 1) {
        const c = objects.find((o) => o.id === sys.components[0]);
        if (c) { c.plP = (c.plP || 0) + open.length; (c.plPSrc ||= new Set()).add("research"); }
      }
    }
    // Researched masses for single-star systems (otherwise shown per component on the system card).
    const info = STAR_DATA[name];
    const masses = (info?.components || []).filter((x) => x.mass != null);
    if (masses.length) sys.massComponents = masses.map((x) => ({ name: x.name, mass: x.mass }));
    if (masses.length === 1 && sys.components?.length === 1) {
      const c = objects.find((o) => o.id === sys.components[0]);
      if (c && !c.mass) { c.mass = { v: masses[0].mass, src: "research" }; stats.mass.research++; }
    }
    if (info?.planets) sys.plC = info.planets.length;
  }
  for (const o of objects) if (o.plPSrc) o.plPSrc = [...o.plPSrc];

  // Star systems take colour and constellation from their brightest catalog star, falling
  // back to the researched constellation.
  const byId = new Map(objects.map((o) => [o.id, o]));
  const conByName = Object.fromEntries(Object.entries(CONSTELLATIONS).map(([k, v]) => [v.toLowerCase(), k]));
  for (const sys of objects.filter((o) => o.type === "star system")) {
    const comps = (sys.components || []).map((id) => byId.get(id)).filter(Boolean);
    const primary = comps.filter((c) => c.tc != null).sort((a, b) => (a.g ?? a.hp ?? 99) - (b.g ?? b.hp ?? 99))[0];
    if (primary) { sys.tc = primary.tc; sys.cc = primary.cc; sys.hex = primary.hex; sys.ccFrom = primary.ccFrom; sys.ccStar = primary.name; }
    const withCon = comps.find((c) => c.con);
    const researched = STAR_DATA[sys.name]?.constellation;
    if (withCon) { sys.con = withCon.con; sys.conName = withCon.conName; }
    else if (researched && conByName[researched.toLowerCase()]) { sys.con = conByName[researched.toLowerCase()]; sys.conName = CONSTELLATIONS[sys.con]; }
  }

  // The Sun.
  const sun = objects.find((o) => o.id === "actual:sol");
  if (sun) {
    sun.tc = 5772; sun.cc = colourClassFor(5772); sun.hex = hexOf(5772); sun.ccFrom = "sun";
    sun.mass = { v: 1, src: "definition" };
    sun.mh = { v: 0, kind: "[M/H]", src: "definition" };
    sun.plC = 8;
  }
  return stats;
}
